                // 5.67.9  = Consumer 4 (Spüler)
                // 5.67.10 = Consumer 5 (BWWP)
                // 5.67.11 = Consumer 6 (Klima)
                // 5.67.12 = Consumer 7 (Pumpe) -- COMPLETES 7-BUBBLE PARITY
                'consumer_1_sparkline_entity',
